    // about.html
    about_using_html: "Find a record, follow a topic, or check the proof behind a link with <a href=\"/guide/\">Using CityScroll</a>. The guide shows which sources we use. It explains gaps in the data, flags, and past patterns.",
    about_maintainers: "Maintainers",
    about_team_html: "CityScroll is maintained by Anna Bao, James Carroll, Dev Doshi, and Michael Sheehan. Reach the team at <a href=\"mailto:team@cityscroll.org\">team@cityscroll.org</a>. The site is open source. <a href=\"https://github.com/cityscroll/cityscroll-app\">Read the code on GitHub</a> to see how it works or help make it better.",
    about_access_html: "CityScroll aims to meet <b>WCAG 2.2 Level AA</b>. If a page or a tool is hard to use, please tell us in the feedback form. We can then look into it.",
    about_destination_0: "Flags and thresholds",
    about_destination_1: "Historical patterns",
    about_destination_2: "Eligible-list timing",
    about_destination_3: "Property sale timing",
    about_destination_4: "Tax lien progression",
    about_destination_5: "Zoning case history",
    about_destination_6: "Applicant history",
    about_h_what: "What this is",
    about_p_what_html: "CityScroll helps you see what New York City government is doing and what you can do next. It brings related public records together and links to the official city sources behind them. CityScroll is independent. It is not part of city government. For dates, decisions, and instructions, check the official notice.",
    about_h_content: "About our content",
    about_p_content_html: "CityScroll uses generative artificial intelligence (AI) to draft headings and plain-language explanations. A human reviews and edits this content before it goes live. AI does not create or change the official records shown on the site.",
    about_flag_method_html: "Our flag methods draw on the <a href=\"https://www.open-contracting.org/resources/red-flags-in-public-procurement-a-guide-to-using-data-to-detect-and-mitigate-risks/\" target=\"_blank\" rel=\"noopener noreferrer\">Open Contracting guide to red flags in public procurement<span class=\"sr-only\"> (opens in new tab)</span></a>.",
    about_h_feedback: "Send feedback",
    about_p_feedback: "Found a bug, want a feature, or have a thought? Send it here. We read everything. No account needed.",
    about_email_us_html: "Or email us: <a href=\"mailto:feedback@cityscroll.org\">feedback@cityscroll.org</a>",
    about_label_kind: "What kind?",
    fb_cat_bug: "Bug",
    fb_cat_feature: "Feature idea",
    fb_cat_general: "General",
    about_label_message: "Your message",
    about_pasttask_optional_badge: "Optional",
    about_pasttask_summary: "Describe a past attempt",
    about_pasttask_task_html: "<b>The task:</b> What were you actually trying to get done?",
    about_pasttask_breakdown_html: "<b>Where it broke down:</b> What happened, or where did it stop working the way you expected?",
    about_pasttask_workaround_html: "<b>What you did instead:</b> Did you find another way, give up, or leave it unfinished?",
    about_pasttask_note: "These are just prompts. Write your answer below, in your own words — there's no separate field to fill in.",
    about_ph_message: "What happened, what you'd want, or anything else — the more specific the better.",
    about_label_email: "Email",
    about_label_email_opt: "— optional, only if you'd like a reply",
    about_btn_send: "Send feedback →",
    about_note_feedback_html: "If you add your email, we only use it to reply. Each submission also saves your IP address and browser for a short time to stop spam.",
    about_err_short: "Add a little more detail — at least a sentence.",
    about_err_long: "That's a bit long — please keep it under 2,000 characters.",
    about_err_bademail: "That email address looks off — leave it blank if you don't want a reply.",
